fields=['index','slug','word','pronunciation','tagline','definition','etymology','sections','literary','art_caption','accent','theme']
for d in items:
    stem=f"{d['index']:02d}-{d['slug']}"
    (B/f'{stem}.json').write_text(json.dumps({k:d[k] for k in fields},ensure_ascii=False,indent=2)+'\n')
    note=f"# {d['word']}\n\n*{d['tagline']}*\n\nPronunciation (approximate): **{d['pronunciation']}**.\n\n{d['definition']}\n\n## The word and its history\n\n{d['etymology']}\n\n"
    for s in d['sections']:
        note+=f"### {s['heading']}\n\n{s['text']}\n\n"
    note+=f"## A closer reading\n\n{d['deep']}\n\n## An original labyrinthine sentence\n\n> {d['literary']}\n\n## The image\n\n{d['art_caption']} Locally rendered procedural artwork; its geometry is explanatory metaphor, not measured evidence.\n\n## Further reading\n\n{d['read']}\n"
    (N/f'{stem}.md').write_text(note)
    wc=lambda s:len(re.findall(r'\S+',s))
    checks={'definition':wc(d['definition']),'etymology':wc(d['etymology']),'sections':[wc(s['text']) for s in d['sections']],'literary':wc(d['literary']),'essay':wc(note)}
    print(stem,checks)
